//! A future event owns its ordinary Instead program after the registrant leaves.
use ironsmith::{CardDefinition,Effect,GameState,ObjectId,PlayerId,Zone};
use ironsmith::effects::{EffectContext,execute_effect};
use ironsmith_compiled_artifact::CompiledCardArtifact;
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
fn definitions(text:&str)->[CardDefinition;2]{let (result,loss)=ironsmith_compiler::parse_loss::capture(||ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact("Timed event program",text,false)));assert!(!loss.is_lossy(),"{}",loss.reasons_text());let (artifact,direct)=result.unwrap();let decoded=CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();assert_eq!(decoded,artifact);[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&decoded).unwrap()]}
fn kill(g:&mut GameState,id:ObjectId){execute_effect(g,&Effect::new(ironsmith::effects::DestroyEffect::with_spec(ironsmith::target::ChooseSpec::SpecificObject(id))),&mut EffectContext::new_default(id,A)).unwrap();}
#[test]
fn temporary_event_program_is_global_until_cleanup_and_event_it_is_not_registration_it(){
 let rules="Type: Sorcery\nIf a nontoken creature you control would die this turn, do the following instead: [Exile it; You gain 1 life].";
 for program in definitions(rules){let mut g=GameState::new(vec!["A".into(),"B".into()],20);let source=g.create_object_from_definition(&program,A,Zone::Stack);let creature=ironsmith_compiler_runtime::compile_to_runtime_definition("Victim","Type: Creature\nPower/Toughness: 2/2",false).unwrap();let old=g.create_object_from_definition(&creature,A,Zone::Battlefield);let old_stable=g.object(old).unwrap().stable_id;let mut ctx=EffectContext::new_default(source,A);for effect in program.spell_effect.as_ref().unwrap().all_effects(){execute_effect(&mut g,effect,&mut ctx).unwrap();}drop(ctx);g.move_object(source,Zone::Graveyard,ironsmith::events::EventCause::effect()).unwrap();let future=g.create_object_from_definition(&creature,A,Zone::Battlefield);let future_stable=g.object(future).unwrap().stable_id;let opponent=g.create_object_from_definition(&creature,B,Zone::Battlefield);let opponent_stable=g.object(opponent).unwrap().stable_id;kill(&mut g,old);kill(&mut g,future);kill(&mut g,opponent);assert_eq!(g.object(g.find_object_by_stable_id(old_stable).unwrap()).unwrap().zone,Zone::Exile);assert_eq!(g.object(g.find_object_by_stable_id(future_stable).unwrap()).unwrap().zone,Zone::Exile);assert_eq!(g.object(g.find_object_by_stable_id(opponent_stable).unwrap()).unwrap().zone,Zone::Graveyard);assert_eq!(g.player(A).unwrap().life,22);ironsmith::turn::execute_cleanup_step(&mut g);let later=g.create_object_from_definition(&creature,A,Zone::Battlefield);let later_stable=g.object(later).unwrap().stable_id;kill(&mut g,later);assert_eq!(g.object(g.find_object_by_stable_id(later_stable).unwrap()).unwrap().zone,Zone::Graveyard);assert_eq!(g.player(A).unwrap().life,22);}
}
